function positiveInt(value){return Number.isSafeInteger(Number(value))&&Number(value)>0}
function returnedQty(issueId){return state.movements.filter(m=>m.type==='退货入库'&&m.issueId===issueId).reduce((n,m)=>n+m.qty,0)}
function addMovement(it,qty,type,reason,details={}){
 if(!Number.isSafeInteger(qty)||!qty)throw Error('变动数量必须为非零整数');
 if(it.stock+qty<0)throw Error('库存不足，无法完成操作');
 if(qty<0){let lots=state.batches.filter(b=>b.itemId===it.id&&b.qty>0).sort((a,b)=>(a.expiry||'9999-12-31').localeCompare(b.expiry||'9999-12-31')||a.receivedAt.localeCompare(b.receivedAt));if(lots.reduce((n,b)=>n+b.qty,0)<-qty)throw Error('可用批次库存不足');let remaining=-qty;for(const lot of lots){let used=Math.min(remaining,lot.qty);lot.qty-=used;remaining-=used;if(!remaining)break}}
 else state.batches.push({id:uid('LOT'),itemId:it.id,qty,code:details.batch||uid('B'),expiry:details.expiry||'',supplier:details.supplier||'',receivedAt:date()});
 it.stock+=qty;if(details.price>0)it.price=Number(details.price);
 it.expiry=state.batches.filter(b=>b.itemId===it.id&&b.qty>0&&b.expiry).map(b=>b.expiry).sort()[0]||'';
 state.movements.push({id:uid(qty>0?'RK':'CK'),itemId:it.id,type,qty,price:Number(details.price||it.price||0),supplier:details.supplier||'',batch:details.batch||'',operator:user().name,reason,time:now().slice(0,16).replace('T',' '),dept:details.dept||user().dept,taskId:details.taskId||'',issueId:details.issueId||''})
}
