function batchDetail(id){const it=item(id),lots=state.batches.filter(x=>x.itemId===id).slice().sort((a,b)=>(a.expiry||'9999-12-31').localeCompare(b.expiry||'9999-12-31')),expiryCell=lot=>{if(lot.qty<=0)return badge('已耗尽','neutral');if(!lot.expiry)return badge('长期有效','neutral');const expired=lot.expiry<date(),soon=!expired&&lot.expiry<=days(30);return`<span class="batch-expiry"><b>${E(lot.expiry)}</b>${badge(expired?'已过期':soon?'即将过期':'有效',expired?'danger':soon?'warning':'')}</span>`};showModal(`${it.name} · 批次库存`,`<div class="batch-summary"><span><small>当前库存</small><b>${it.stock} ${E(it.unit)}</b></span><span><small>在库批次</small><b>${lots.filter(x=>x.qty>0).length} 个</b></span></div>${table(['批次号','剩余数量','供应商','入库日期','批次效期'],lots.map(l=>row([`<strong>${E(l.code)}</strong>`,`<strong>${l.qty}</strong> ${E(it.unit)}`,E(l.supplier||'—'),E(l.receivedAt||'—'),expiryCell(l)])),'暂无批次记录')}`,'','',true)}
function inboundDetail(id){const movement=state.movements.find(x=>x.id===id),current=item(movement?.itemId);if(!movement||!current)return fail('入库记录不存在');const relation=movement.taskId?`采购任务 ${movement.taskId}`:movement.issueId?`领用单 ${movement.issueId}`:'独立入库',detail=(label,value)=>`<div><span>${label}</span><b>${value}</b></div>`;showModal('入库详情',`<div class="inbound-detail-hero"><div class="inbound-detail-icon">${navIcons.inbound}</div><div class="inbound-detail-heading"><span>入库单号</span><strong>${E(movement.id)}</strong><p>${E(movement.time)} · ${E(movement.operator||'—')}</p></div>${badge(movement.type,movement.type==='库存调整'?'blue':'')}</div><div class="inbound-detail-stats"><div><span>入库数量</span><strong>+${fmt(movement.qty)}</strong><small>${E(current.unit)}</small></div><div><span>入库单价</span><strong>${money(movement.price)}</strong><small>/ ${E(current.unit)}</small></div><div class="total"><span>入库金额</span><strong>${money(movement.qty*movement.price)}</strong><small>本次入库合计</small></div></div><div class="inbound-detail-grid"><section><div class="inbound-detail-title"><span class="item-icon">${categoryIcons[current.category]||navIcons.items}</span><div><b>物品信息</b><small>${E(current.name)} · ${E(current.code)}</small></div></div><div class="inbound-detail-list">${detail('物品规格',E(current.spec||'—'))}${detail('物品分类',E(current.category||'—'))}${detail('库存位置',E(current.location||'—'))}${detail('计量单位',E(current.unit||'—'))}</div></section><section><div class="inbound-detail-title"><span class="item-icon">${navIcons.purchasing}</span><div><b>入库信息</b><small>${E(relation)}</small></div></div><div class="inbound-detail-list">${detail('供应商',E(movement.supplier||'—'))}${detail('批次号',E(movement.batch||'—'))}${detail('所属部门',E(movement.dept||'—'))}${detail('关联业务',E(relation))}</div></section></div><div class="inbound-detail-reason"><span>入库原因</span><p>${E(movement.reason||'—')}</p></div>`,'','',true)}
function outboundDetail(id){const issue=state.issues.find(x=>x.id===id),current=item(issue?.itemId),movement=state.movements.find(x=>x.issueId===id&&x.type==='领用出库');if(!issue||!current||!movement)return fail('出库记录不存在');const returned=returnedQty(id),detail=(label,value)=>`<div><span>${label}</span><b>${value}</b></div>`;showModal('出库详情',`<div class="inbound-detail-hero outbound-detail-hero"><div class="inbound-detail-icon">${navIcons.issues}</div><div class="inbound-detail-heading"><span>出库单号</span><strong>${E(movement.id)}</strong><p>${E(movement.time)} · ${E(movement.operator||'—')}</p></div>${badge('已出库','warning')}</div><div class="inbound-detail-stats outbound-detail-stats"><div><span>出库数量</span><strong>-${fmt(issue.qty)}</strong><small>${E(current.unit)}</small></div><div><span>已退回数量</span><strong>${fmt(returned)}</strong><small>${E(current.unit)}</small></div><div class="total"><span>实际领用</span><strong>${fmt(issue.qty-returned)}</strong><small>${E(current.unit)}</small></div></div><div class="inbound-detail-grid"><section><div class="inbound-detail-title"><span class="item-icon">${categoryIcons[current.category]||navIcons.items}</span><div><b>物品信息</b><small>${E(current.name)} · ${E(current.code)}</small></div></div><div class="inbound-detail-list">${detail('物品规格',E(current.spec||'—'))}${detail('物品分类',E(current.category||'—'))}${detail('库存位置',E(current.location||'—'))}${detail('计量单位',E(current.unit||'—'))}</div></section><section><div class="inbound-detail-title"><span class="item-icon">${navIcons.issues}</span><div><b>领用信息</b><small>${E(issue.id)}</small></div></div><div class="inbound-detail-list">${detail('领用人',E(issue.requester||'—'))}${detail('所属部门',E(issue.dept||'—'))}${detail('申请日期',E(issue.created||'—'))}${detail('出库操作人',E(movement.operator||'—'))}</div></section></div><div class="inbound-detail-reason outbound-detail-reason"><span>领用用途</span><p>${E(issue.purpose||'—')}</p></div>`,'','',true)}
function inboundForm(defaultIssueId=''){const returnOptions=[['','请选择已出库领用单'],...state.issues.filter(x=>x.status==='completed'&&x.qty>returnedQty(x.id)).map(x=>[x.id,`${x.id} · ${item(x.itemId)?.name} · ${x.requester} · 可退 ${x.qty-returnedQty(x.id)}`])];showModal('新增入库 / 库存调整',`<div class="form-grid">${select('业务类型 *','type',[['采购入库','采购入库'],['退货入库','退货入库'],['库存调整','库存调整']])}${select('物品 *','itemId',itemOptions(false))}<div class="return-link full" hidden>${select('关联原领用单 *','issueId',returnOptions,defaultIssueId)}</div>${input('变动数量 *','qty','number',1,'required step="1" min="-999999"')}${input('单价（元）','price','number',0,'min="0" step="0.01"')}${supplierSelect('供应商（采购入库必填）')}${input('批次号（采购入库必填）','batch')}${input('有效期（按批次预警）','expiry','date')}${input('操作人','operator','text',user().name,'disabled')}<label class="field full">变化原因 *<textarea name="reason" required placeholder="请填写此次入库或调整的原因"></textarea></label></div><p class="hint section">采购入库须填写供应商和批次；退回入库须关联原领用单，且不能超过未退回数量。</p>`,'确认入库 / 调整','inbound');if(defaultIssueId)nextTick(()=>{let form=document.querySelector('#dialogForm');setEnhancedValue(form,'type','退货入库');syncInboundType(form)})}
function syncInboundType(form){let type=form.querySelector('[name="type"]')?.value,group=form.querySelector('.return-link'),issueId=form.querySelector('[name="issueId"]')?.value;if(!group)return;group.hidden=type!=='退货入库';if(type==='退货入库'&&issueId){let issue=state.issues.find(x=>x.id===issueId);if(issue)setEnhancedValue(form,'itemId',issue.itemId)}}
function issueForm(){showModal('发起领用申请',`<div class="form-grid">${select('领用物品 *','itemId',itemOptions())}${input('数量 *','qty','number',1,'required min="1" step="1"')}${input('领用人 *','requester','text',user().name,'required readonly')}${select('所属部门 *','dept',departmentOptions(),user().dept)}<label class="field full">领用用途 *<textarea name="purpose" required></textarea></label></div><p class="hint section">停用物品不可领用，出库数量不能超过当前可用库存。</p>`,'提交申请','issue')}
function lineHTML(it='',qty=1){return `<div class="line-item">${select('采购物品 *','itemId',itemOptions(),it)}${input('数量 *','qty','number',qty,'min="1" step="1" required')}<button type="button" class="remove" data-remove-line title="移除该物品">×</button></div>`}
function requestForm(id='',preferred=''){const req=id?state.requests.find(x=>x.id===id):null;showModal(req?'编辑采购申请':'新建采购申请',`<div class="request-line-head"><span>${fieldLabel('采购物品 *')}</span><span>${fieldLabel('数量 *')}</span><span></span></div><div id="requestLines">${(req?.lines||[{itemId:preferred||state.items.find(x=>x.active)?.id,qty:1}]).map(x=>lineHTML(x.itemId,x.qty)).join('')}</div><button type="button" class="button small" data-add-line>＋ 添加物品</button><div class="form-grid section">${input('期望到货日期 *','expected','date',req?.expected||days(7),`required min="${date()}"`)}${select('申请部门 *','dept',departmentOptions(),req?.dept||user().dept)}<label class="field full">采购用途 *<textarea name="purpose" required>${E(req?.purpose||'')}</textarea></label></div><p class="hint section">保存草稿后可再次编辑；提交后需审批通过才会产生采购任务。</p>`,'保存草稿','request:'+id,true)}
function taskForm(id){const t=state.tasks.find(x=>x.id===id);if(!t||t.received>0||['partial','completed'].includes(t.status))return fail('任务已有到货记录，采购报价已锁定，不能再修改');const it=item(t.itemId),remaining=t.qty-t.received,statusOptions=t.status==='ordered'?[['ordered','采购中']]:[['pending','待采购'],['ordered','采购中']];showModal(t.status==='ordered'?'调整采购信息':'完善采购信息',`<div class="purchase-task-summary"><span class="purchase-task-icon">${categoryIcons[it?.category]||navIcons.items}</span><div><small>采购物品</small><b>${E(it?.name||'—')}</b></div><div><small>采购数量</small><b>${t.qty} ${E(it?.unit||'')}</b></div><div><small>待到货</small><b>${remaining} ${E(it?.unit||'')}</b></div></div><div class="form-grid purchase-task-form">${supplierSelect('供应商 *',t.supplier)}${input('采购单价（元）*','price','number',t.price||'','required min="0.01" step="0.01" placeholder="请输入采购单价"')}${input('预计到货日期 *','eta','date',t.eta||days(5),'required')}${select('采购状态 *','status',statusOptions,t.status)}</div><div class="purchase-task-note"><span>说明</span>${t.status==='ordered'?'采购已确认，状态不可退回；首次到货后供应商与采购单价将锁定。':'将状态设为“采购中”后才可以登记到货。'}</div>`,'保存采购信息','task:'+id)}
function receiveForm(id){const t=state.tasks.find(x=>x.id===id);if(!t?.supplier||!t.price||!t.eta||t.status==='pending')return fail('请先完善采购信息，并将采购状态设为“采购中”');const it=item(t.itemId),remaining=t.qty-t.received;showModal('登记实际到货',`<div class="arrival-summary"><div class="arrival-item"><span class="purchase-task-icon">${categoryIcons[it?.category]||navIcons.items}</span><span><small>采购物品</small><b>${E(it?.name||'—')}</b></span></div><div><small>采购数量</small><b>${t.qty} ${E(it?.unit||'')}</b></div><div><small>已到货</small><b>${t.received} ${E(it?.unit||'')}</b></div><div class="arrival-remaining"><small>本次最多可收</small><b>${remaining} ${E(it?.unit||'')}</b></div></div><div class="arrival-contract"><div><small>供应商</small><b>${E(t.supplier)}</b></div><div><small>采购单价</small><b>${money(t.price)} / ${E(it?.unit||'件')}</b></div><div><small>预计到货</small><b>${E(t.eta)}</b></div></div><div class="arrival-section-title"><b>本次到货信息</b><span>实际入库数量将直接增加库存</span></div><div class="form-grid arrival-task-form">${input('本次到货数量 *','qty','number',remaining,`required min="1" max="${remaining}" step="1" placeholder="最多 ${remaining}"`)}${input('到货批次 *','batch','text',uid('B'),'required placeholder="请输入到货批次"')}${input('有效期','expiry','date')}</div>`,'确认入库','receive:'+id,true)}
function requestDetail(id){const x=state.requests.find(y=>y.id===id),saved=state.audits.filter(log=>log.requestId===id),fallback=[{action:'创建申请',operator:x.requester,role:'申请人',time:`${x.created} 09:00`,detail:`由${x.dept}发起采购申请`},...x.status!=='draft'?[{action:({submitted:'提交审批',approved:'审批通过',rejected:'审批驳回',completed:'采购完成'})[x.status]||'状态更新',operator:x.approver||x.requester,role:x.approver?'审批人':'申请人',time:`${x.created} 10:00`,detail:x.rejectReason||`当前状态：${requestStatusBadge(x).replace(/<[^>]+>/g,'')}`}]:[]],logs=(saved.length?saved:fallback).slice().reverse();const lineRows=x.lines.map(line=>{const current=item(line.itemId);return`<div class="request-detail-line"><span class="item-icon">${categoryIcons[current?.category]||navIcons.items}</span><span><b>${E(current?.name||'物品已删除')}</b><small>${E(current?.code||'—')} · ${E(current?.spec||'—')}</small></span><strong>${line.qty} ${E(current?.unit||'')}</strong></div>`}).join('');showModal('采购申请详情',`<div class="request-detail-hero"><div><span>申请编号</span><strong>${E(x.id)}</strong><p>${E(x.purpose)}</p></div>${requestStatusBadge(x)}</div><div class="request-detail-meta"><div><span>申请人</span><b>${E(x.requester)}</b></div><div><span>申请部门</span><b>${E(x.dept)}</b></div><div><span>期望到货</span><b>${E(x.expected)}</b></div><div><span>审批人</span><b>${E(x.approver||'—')}</b></div></div>${x.rejectReason?`<div class="request-reject-reason"><span>驳回原因</span>${E(x.rejectReason)}</div>`:''}<div class="request-detail-columns"><section><div class="request-section-head"><b>采购物品</b><span>${x.lines.length} 项</span></div><div class="request-detail-lines">${lineRows}</div></section><section><div class="request-section-head"><b>操作记录</b><span>${logs.length} 条</span></div><div class="audit-timeline request-audits">${logs.map(log=>`<div><i></i><span><b>${E(log.action)}</b><small>${E(log.operator)} · ${E(log.role)}</small><p>${E(log.time)}${log.detail?' · '+E(log.detail):''}</p></span></div>`).join('')}</div></section></div>`,'','',true)}
function taskHistory(id){let arr=state.movements.filter(m=>m.taskId===id);showModal('关联入库记录',table(['入库单号','时间','到货数量','供应商 / 批次'],arr.map(m=>row([E(m.id),E(m.time),`+${m.qty}`,`${E(m.supplier)} / ${E(m.batch)}`]))),'','',true)}

function exportRecords(){const q=(filter.recQ||'').toLowerCase(),person=(filter.personQ||'').toLowerCase(),dept=filter.recDept||'',cat=filter.recCat||'',typ=filter.recType||'',from=filter.recFrom||'',to=filter.recTo||'',detail=recordsTab.value==='issues';const arr=detail?state.issues.filter(x=>x.status==='completed'&&(!dept||x.dept===dept)&&x.requester.toLowerCase().includes(person)&&(!from||(x.completed||x.created)>=from)&&(!to||(x.completed||x.created)<=to)):state.movements.filter(m=>{let it=item(m.itemId);return(it?.name||'').toLowerCase().includes(q)&&(!dept||m.dept===dept)&&(!cat||it?.category===cat)&&(!typ||m.type===typ)&&(!from||m.time.slice(0,10)>=from)&&(!to||m.time.slice(0,10)<=to)});const fields=detail?['领用单号','领用人','部门','物品编码','物品名称','数量','单位','用途','出库日期']:['单号','时间','物品编码','物品名称','分类','操作类型','变动数量','单位','单价','操作人','部门','变化原因'];const quote=(x)=>`"${String(x??'').replaceAll('"','""')}"`;const rows=detail?arr.map(x=>[x.id,x.requester,x.dept,item(x.itemId)?.code,item(x.itemId)?.name,x.qty,item(x.itemId)?.unit,x.purpose,x.completed||x.created]):arr.map(m=>[m.id,m.time,item(m.itemId)?.code,item(m.itemId)?.name,item(m.itemId)?.category,m.type,m.qty,item(m.itemId)?.unit,m.price,m.operator,m.dept,m.reason]);const csv='\ufeff'+[fields,...rows].map(line=>line.map(quote).join(',')).join('\r\n');const link=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.href=url;link.download=`好财-${detail?'领用明细':'库存流水'}-${date()}.csv`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`已导出 ${arr.length} 条${detail?'领用明细':'库存流水'}`)}

function act(action){if(!canAction(action))return fail(permissionMessage(action));let [type,id]=action.split(':');let x,it;switch(type){
case 'recordTab':Object.keys(draftFilter).forEach(k=>delete draftFilter[k]);recordsTab.value=id==='issues'?'issues':'movements';return;
case 'searchFilters':Object.assign(filter,draftFilter);toast('已应用筛选条件');return;
case 'clearFilters':Object.keys(draftFilter).forEach(k=>delete draftFilter[k]);Object.keys(filter).forEach(k=>delete filter[k]);toast('筛选条件已重置');return;
case 'exportRecords':return exportRecords();
case 'newItem':return itemForm();case 'editItem':return itemForm(id);case 'manageDictionaries':return dictionaryForm();case 'itemBatches':return batchDetail(id);
case 'inboundDetail':return inboundDetail(id);
case 'outboundDetail':return outboundDetail(id);
case 'toggleItem':it=item(id);if(it){it.active=!it.active;toast(it.active?'物品已启用':'物品已停用')}return;
case 'newInbound':return inboundForm();case 'returnIssue':return inboundForm(id);case 'newIssue':return issueForm();case 'newRequest':return requestForm();case 'editRequest':return requestForm(id);
case 'purchaseFor':page.value='requests';return requestForm('',id);
case 'goTask':x=state.tasks.find(task=>task.id===id);if(!x)return fail('关联采购任务不存在');Object.keys(draftFilter).forEach(key=>delete draftFilter[key]);filter.taskQ=x.id;filter.taskStatus='';page.value='purchasing';window.scrollTo(0,0);toast(`已定位采购任务 ${x.id}`);return;
case 'goPurchase':Object.keys(draftFilter).forEach(key=>delete draftFilter[key]);filter.taskQ=id;filter.taskStatus='';page.value='purchasing';window.scrollTo(0,0);return;
case 'approveIssue':x=state.issues.find(y=>y.id===id);it=item(x.itemId);if(x.status!=='pending')return fail('申请状态已变化');if(!it.active||available(it)<x.qty)return fail('物品已停用或可用库存不足，无法审核通过');x.status='approved';x.operator=user().name;toast('审核通过，数量已锁定，等待执行出库');return;
case 'rejectIssue':x=state.issues.find(y=>y.id===id);if(x.status!=='pending'&&x.status!=='approved')return fail('当前状态不可驳回');x.status='rejected';x.operator=user().name;toast('已驳回领用申请');return;
case 'outIssue':x=state.issues.find(y=>y.id===id);it=item(x.itemId);if(x.status!=='approved'||it.stock<x.qty)return fail('库存不足或申请状态已变化');addMovement(it,-x.qty,'领用出库',`${x.purpose} · ${x.requester}`,{dept:x.dept});x.status='completed';x.operator=user().name;x.completed=date();toast('出库成功，库存流水已记录');return;
case 'submitRequest':x=state.requests.find(y=>y.id===id);if(!['draft','rejected'].includes(x.status))return fail('当前申请不可提交');if(x.lines.some(l=>!item(l.itemId)?.active))return fail('包含已停用物品，请先编辑申请');x.status='submitted';x.rejectReason='';addAudit(x.id,'提交审批',`提交至${x.dept}负责人`);toast('采购申请已提交审批');return;
case 'approveRequest':x=state.requests.find(y=>y.id===id);if(x.status!=='submitted')return fail('仅待审批申请可审批');if(x.lines.some(l=>!item(l.itemId)?.active))return fail('包含已停用物品，不能审批');x.status='approved';x.approver=user().name;x.lines.forEach(l=>state.tasks.push({id:uid('PC'),requestId:x.id,itemId:l.itemId,qty:l.qty,received:0,supplier:'',price:0,eta:'',status:'pending'}));addAudit(x.id,'审批通过',`生成 ${x.lines.length} 条采购任务`);toast(`审批通过，已生成 ${x.lines.length} 条采购任务`);return;
case 'rejectRequest':x=state.requests.find(y=>y.id===id);if(x.status!=='submitted')return fail('仅待审批申请可驳回');ElMessageBox.prompt('请填写驳回原因，申请人修改后可重新提交。','驳回采购申请',{confirmButtonText:'确认驳回',cancelButtonText:'取消',inputPlaceholder:'请输入具体原因',inputValidator:value=>value?.trim()?true:'驳回原因不能为空',type:'warning'}).then(({value})=>{x.rejectReason=value.trim();x.status='rejected';x.approver=user().name;addAudit(x.id,'审批驳回',x.rejectReason);toast('采购申请已驳回')}).catch(()=>{});return;
case 'viewRequest':return requestDetail(id);case 'editTask':return taskForm(id);case 'receiveTask':return receiveForm(id);case 'taskMovements':return taskHistory(id);
}}
function submitDialog(form){runWithLoading(()=>submitDialogNow(form),document.querySelector('.business-dialog')||document.body)}
function submitDialogNow(form){let kind=form.dataset.kind,[type,id]=kind.split(':'),f=new FormData(form),v=(k)=>String(f.get(k)||'').trim();let x,it,n;if(type==='item'&&!canAction(id?`editItem:${id}`:'newItem'))return fail(permissionMessage('newItem'));if(type==='inbound'&&!canAction('newInbound'))return fail(permissionMessage('newInbound'));if(type==='issue'&&!canAction('newIssue'))return fail(permissionMessage('newIssue'));if(['task','receive'].includes(type)&&!canAction(`editTask:${id}`))return fail(permissionMessage('editTask'));if(type==='request'&&!canAction(id?`editRequest:${id}`:'newRequest'))return fail(permissionMessage('newRequest'));
try{switch(type){
case 'dictionaries':{const parse=name=>[...new Set(f.getAll(name).map(value=>String(value).trim()).filter(Boolean))],categories=parse('categories'),units=parse('units'),locations=parse('locations');if(!categories.length||!units.length||!locations.length)return fail('分类、单位和库存位置均至少保留一项');const missing=state.items.find(current=>!categories.includes(current.category)||!units.includes(current.unit)||!locations.includes(current.location));if(missing)return fail(`“${missing.name}”正在使用被删除的字典值，请先修改物品档案`);state.dictionaries={categories,units,locations};toast('基础字典已更新');break}
case 'item':{let name=v('name'),code=v('code'),barcode=v('barcode'),safety=Number(v('safety'));if(!name||!code||!v('category')||!v('spec')||!v('unit')||!v('location')||!Number.isSafeInteger(safety)||safety<0)return fail('请填写完整物品信息和有效安全库存');if(state.items.some(y=>y.id!==id&&(y.code===code||(barcode&&y.barcode===barcode))))return fail('物品编码或条形码已存在');let data={name,code,barcode,category:v('category'),spec:v('spec'),unit:v('unit'),location:v('location'),safety};if(id)Object.assign(item(id),data);else state.items.push({id:uid('I'),...data,stock:0,price:0,active:true,expiry:''});toast(id?'物品已更新':'物品已创建');break}
case 'inbound':{let inboundType=v('type'),linked=state.issues.find(x=>x.id===v('issueId'));it=inboundType==='退货入库'?item(linked?.itemId):item(v('itemId'));n=Number(v('qty'));let price=Number(v('price'));if(!it||!Number.isSafeInteger(n)||n===0||((inboundType!=='库存调整')&&n<0))return fail('请选择物品并填写有效数量');if(n<0&&-n>available(it))return fail('调整出库不可超过可用库存');if(!v('reason'))return fail('请填写变化原因');if(!Number.isFinite(price)||price<0)return fail('请填写有效单价');if(inboundType==='采购入库'&&(!v('supplier')||!v('batch')||price<=0))return fail('采购入库必须填写供应商、批次及有效单价');if(inboundType==='退货入库'&&(!linked||linked.status!=='completed'||!positiveInt(n)||n>linked.qty-returnedQty(linked.id)))return fail('请关联已出库领用单，且退回数量不能超过未退回数量');let supplier=inboundType==='退货入库'?linked.requester:inboundType==='库存调整'?'内部盘点':v('supplier'),batch=inboundType==='退货入库'?`RET-${linked.id}`:inboundType==='库存调整'?(v('batch')||uid('ADJ')):v('batch');addMovement(it,n,inboundType,inboundType==='退货入库'?`${v('reason')} · 关联 ${linked.id}`:v('reason'),{price,supplier,batch,expiry:v('expiry'),issueId:linked?.id||'',dept:linked?.dept||user().dept});if(inboundType==='采购入库')rememberSupplier(supplier);toast('库存已更新，变动记录已保存');break}
case 'issue':{it=item(v('itemId'));n=Number(v('qty'));if(!it?.active)return fail('已停用物品不可申请领用');if(!positiveInt(n)||n>available(it))return fail(`领用数量不能超过可用库存（${available(it)}）`);if(v('requester')!==user().name||!departments.includes(v('dept'))||!v('purpose'))return fail('请确认领用人、选择有效部门并填写用途');state.issues.push({id:uid('LY'),itemId:it.id,qty:n,requester:user().name,dept:v('dept'),purpose:v('purpose'),status:'pending',created:date()});toast('领用申请已提交');break}
case 'request':{let lines=[...form.querySelectorAll('.line-item')].map(el=>({itemId:el.querySelector('[name="itemId"]').value,qty:Number(el.querySelector('[name="qty"]').value)}));if(!lines.length||lines.some(l=>!item(l.itemId)?.active||!positiveInt(l.qty)))return fail('请至少添加一种有效物品，并填写正整数数量');if(new Set(lines.map(l=>l.itemId)).size!==lines.length)return fail('同一物品请合并为一行');if(!v('expected')||v('expected')<date()||!v('purpose')||!departments.includes(v('dept')))return fail('请填写用途、有效到货日期并选择申请部门');if(id){x=state.requests.find(y=>y.id===id);if(!['draft','rejected'].includes(x.status))return fail('当前状态不可编辑');Object.assign(x,{lines,expected:v('expected'),purpose:v('purpose'),dept:v('dept'),status:'draft'});addAudit(x.id,'修改草稿','更新采购物品、数量或申请信息')}else{x={id:uid('CG'),lines,expected:v('expected'),purpose:v('purpose'),dept:v('dept'),requester:user().name,status:'draft',created:date()};state.requests.push(x);addAudit(x.id,'创建申请','保存采购申请草稿')}toast('采购申请草稿已保存，可在列表中提交');break}
case 'task':{x=state.tasks.find(y=>y.id===id);n=Number(v('price'));if(!x||x.received>0||['partial','completed'].includes(x.status))return fail('任务已有到货记录，采购报价已锁定，不能再修改');if(x.status==='ordered'&&v('status')!=='ordered')return fail('采购已确认，不能退回待采购状态');if(!['pending','ordered'].includes(v('status'))||!v('supplier')||!v('eta')||!Number.isFinite(n)||n<=0)return fail('请填写供应商、价格、预计到货日期和有效采购状态');Object.assign(x,{supplier:v('supplier'),price:n,eta:v('eta'),status:v('status')});rememberSupplier(v('supplier'));addAudit(x.requestId,x.status==='ordered'?'确认采购':'更新采购信息',`${item(x.itemId)?.name} · ${v('supplier')} · ${money(n)}`);toast(x.status==='ordered'?'采购已确认，可以登记到货':'采购信息已保存');break}
case 'receive':{x=state.tasks.find(y=>y.id===id);if(!x?.supplier||!x.price||!x.eta||x.status==='pending')return fail('采购信息尚未完善，不能登记到货');it=item(x.itemId);n=Number(v('qty'));if(!positiveInt(n)||n>x.qty-x.received)return fail('到货数量不能超过未到货数量');if(!v('batch'))return fail('请填写到货批次');addMovement(it,n,'采购入库',`采购任务 ${x.id} 分批到货`,{supplier:x.supplier,batch:v('batch'),price:x.price,expiry:v('expiry'),taskId:id});x.received+=n;x.status=x.received===x.qty?'completed':'partial';let req=state.requests.find(y=>y.id===x.requestId);if(req&&state.tasks.filter(y=>y.requestId===req.id).every(y=>y.status==='completed'))req.status='completed';addAudit(x.requestId,x.status==='completed'?'采购到货完成':'采购部分到货',`${it.name} 本次到货 ${n} ${it.unit}，累计 ${x.received}/${x.qty}`);toast(x.status==='completed'?'全部到货，采购申请已完成':'部分到货已入库，剩余数量待处理');break}
default:return fail('未知表单操作')}
closeModal();return true}catch(e){return fail(e.message||'操作失败')}}

document.querySelector('#modalRoot').addEventListener('click',e=>{if(e.target.matches('[data-close]')||e.target.classList.contains('modal-backdrop'))closeModal();if(e.target.closest('[data-add-line]')){let lines=document.querySelector('#requestLines');lines?.insertAdjacentHTML('beforeend',lineHTML());enhanceDialogControls(lines?.lastElementChild)}if(e.target.closest('[data-remove-line]')){let rows=document.querySelectorAll('.line-item');if(rows.length>1)e.target.closest('.line-item').remove();else toast('至少保留一项物品')}});
document.querySelector('#modalRoot').addEventListener('click',e=>{const add=e.target.closest('[data-add-dict]'),remove=e.target.closest('[data-remove-dict]');if(add){const card=add.closest('.dictionary-card'),input=card.querySelector('[data-native]'),value=input.value.trim(),name=add.dataset.addDict;if(!value)return fail('请输入要添加的内容');if([...card.querySelectorAll(`input[name="${name}"]`)].some(item=>item.value===value))return fail('该选项已存在');card.querySelector('.dictionary-tags').insertAdjacentHTML('beforeend',`<span class="dictionary-tag"><input type="hidden" name="${name}" value="${E(value)}"><span>${E(value)}</span><button type="button" data-remove-dict aria-label="删除 ${E(value)}">×</button></span>`);input.value='';card.querySelector('.dictionary-card-head span').textContent=`${card.querySelectorAll('.dictionary-tag').length} 项`;input.focus()}if(remove){const card=remove.closest('.dictionary-card');remove.closest('.dictionary-tag').remove();card.querySelector('.dictionary-card-head span').textContent=`${card.querySelectorAll('.dictionary-tag').length} 项`}});
document.querySelector('#modalRoot').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-native]')){e.preventDefault();e.target.closest('.dictionary-card').querySelector('[data-add-dict]').click()}});
document.querySelector('#modalRoot').addEventListener('change',e=>{let form=e.target.closest('form[data-kind="inbound"]');if(form)syncInboundType(form)});
createApp({setup(){const currentUser=computed(()=>users[state.role]),warningCount=computed(()=>warnings().length),pageHTML=computed(()=>applyPermissions(refineIcons(decorateToolbar(({dashboard,items,inbound,issues,requests,purchasing,alerts,records})[page.value](),page.value)))),themeOpen=ref(false),searchOpen=ref(false),globalQuery=ref('');
watch(pageHTML,()=>nextTick(()=>{enhanceFilterControls();enhanceTablePagination()}),{flush:'post',immediate:true});
const globalResults=computed(()=>{const q=globalQuery.value.trim().toLowerCase();if(!q)return[{type:'nav',id:'items',page:'items',title:'物品档案',subtitle:'浏览全部物品与库存'},{type:'nav',id:'requests',page:'requests',title:'采购申请',subtitle:'创建与审批采购申请'},{type:'nav',id:'records',page:'records',title:'库存记录',subtitle:'查看和导出库存流水'}];return[...state.items.filter(x=>(x.name+x.code+x.barcode).toLowerCase().includes(q)).map(x=>({type:'item',id:x.id,page:'items',title:x.name,subtitle:`物品 · ${x.code} · 库存 ${x.stock}`})),...state.requests.filter(x=>(x.id+x.purpose+x.requester).toLowerCase().includes(q)).map(x=>({type:'request',id:x.id,page:'requests',title:x.id,subtitle:`采购申请 · ${x.requester} · ${x.purpose}`})),...state.tasks.filter(x=>(x.id+x.supplier+(item(x.itemId)?.name||'')).toLowerCase().includes(q)).map(x=>({type:'task',id:x.id,page:'purchasing',title:x.id,subtitle:`采购任务 · ${item(x.itemId)?.name||''}`}))].slice(0,8)});
function go(p){Object.keys(draftFilter).forEach(k=>delete draftFilter[k]);page.value=p;searchOpen.value=false;window.scrollTo(0,0)}function openResult(result){go(result.page);if(result.type==='item')filter.itemsQ=item(result.id)?.name||'';if(result.type==='request')nextTick(()=>requestDetail(result.id));if(result.type==='task'&&canAction(`editTask:${result.id}`))nextTick(()=>state.tasks.find(x=>x.id===result.id)?.status==='completed'?taskHistory(result.id):taskForm(result.id))}function reset(){ElMessageBox.confirm('重置后，当前浏览器中的申请、库存和操作记录都会恢复为初始演示数据。','重置演示数据',{confirmButtonText:'确认重置',cancelButtonText:'取消',type:'warning'}).then(()=>{Object.assign(state,seed());page.value='dashboard';Object.keys(draftFilter).forEach(k=>delete draftFilter[k]);Object.keys(filter).forEach(k=>delete filter[k]);toast('演示数据已重置')}).catch(()=>{})}
watch(searchOpen,opened=>{if(opened){globalQuery.value='';nextTick(()=>document.querySelector('.search-dialog-input input')?.focus())}});
const closeAppearance=(event)=>{if(!event.target.closest('.appearance-wrap'))themeOpen.value=false};const keyHandler=(event)=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchOpen.value=true}else if(event.key==='Escape'){searchOpen.value=false;themeOpen.value=false}else if(event.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){event.preventDefault();searchOpen.value=true}};onMounted(()=>{document.addEventListener('click',closeAppearance);document.addEventListener('keydown',keyHandler);nextTick(()=>requestAnimationFrame(()=>document.querySelector('#boot-screen')?.remove()))});onUnmounted(()=>{document.removeEventListener('click',closeAppearance);document.removeEventListener('keydown',keyHandler)});
function onContentClick(e){const target=e.target.closest('[data-action],[data-page]');if(!target)return;if(target.dataset.page)return go(target.dataset.page);const action=target.dataset.action;if(/^(toggleItem|approveIssue|rejectIssue|outIssue|submitRequest|approveRequest|rejectRequest):/.test(action))runWithLoading(()=>act(action),document.querySelector('.content')||document.body);else act(action)}function onFilter(e){const el=e.target;if(el.dataset.filter)draftFilter[el.dataset.filter]=el.value}function onFilterEnter(e){if(e.target.closest('.toolbar')){e.preventDefault();act('searchFilters')}}return{names,users,navIcons,state,page,currentUser,warningCount,pageHTML,go,reset,onContentClick,onFilter,onFilterEnter,appearance,accentOptions,themeOpen,searchOpen,globalQuery,globalResults,openResult}}}).component('ElMenu',ElMenu).component('ElMenuItem',ElMenuItem).component('ElSelect',ElSelect).component('ElOption',ElOption).component('ElButton',ElButton).component('ElDialog',ElDialog).component('ElInput',ElInput).mount('#app');
